    43	\begin{theorem}[Physics formalization target]
    44	\label{thm:physics:IPhO_2026_3_A_3:target}
    45	\uses{thm:IPhO2026Problems_problem_IPhO_2026_3_A_3:dW_eq_mu0_V_H_dM}
    46	The assigned autoformalize agent should translate this physics problem into Lean declarations in the covered file, with theorem and lemma proof bodies written as `by sorry`.
    47	\end{theorem}
    48	\begin{proof}
    49	This is an autoformalization task, not a proof task. Produce faithful statements that can later be proved without weakening the source contract.
    50	\end{proof}
    51	% NOTE: PhysLean grounding reconciliation (planner-recorded, iter-004): positive targeted-import case — the covered file genuinely uses `Physlib.Electromagnetism.Dynamics.Basic` (the `FreeSpace` structure, `μ₀`, in the constitutive law `ConstitutiveBH` and the `PmTVariation`/`PmTWorkBudget` structures); the blanket domain-import check is satisfied and no further import is added. PhysLean has no thermodynamic work-identity/First-Law library for magnetic media (LeanExplore near misses only), so `dW = μ₀ V H dM` and the heat/energy budgets are faithful local laws.
    52	% --- Archon autoformalization helper ledger (added iter-008, coverage-debt batch for T3-A3) ---
    53	% Every named Lean declaration of the covered file gets a blueprint entry;
    54	% \uses{} reflects the actual Lean dependency structure read first-hand.
    55	
    56	\subsection*{Named quantities and governing-law hypotheses}
    57	
    58	\begin{definition}[Thin paramagnetic torus]
    59	\label{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTTorus}
    60	\lean{IPhO2026.T3A3.PmTTorus}
    61	Geometry of the thin paramagnetic torus: mean radius $R$, winding radius
    62	$r \ll R$, cross-sectional area $A$, volume $V$, with positivity
    63	certificates $0 < r$, $r < R$, $A > 0$, $V > 0$ and the thin-torus volume
    64	identity $V = 2\pi R\,A$ (an assumed geometric input, not derived).
    65	\end{definition}
    66	\begin{proof}
    67	Packaging/definition; nothing derived.
    68	\end{proof}
    69	
    70	\begin{definition}[Dense winding]
    71	\label{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTWinding}
    72	\lean{IPhO2026.T3A3.PmTWinding}
    73	The insulated wire wound densely around the torus: $N$ turns with $N \ge 1$,
    74	carrying an instantaneous signed current $I$ (A); the sign of $I$ fixes the
    75	orientation of the drive relative to the chosen positive $H$ direction.
    76	\end{definition}
    77	\begin{proof}
    78	Packaging/definition; nothing derived.
    79	\end{proof}
    80	
    81	\begin{definition}[Ampère's-law predicate for the torus]
    82	\label{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:AmpereLawTorus}
    83	\lean{IPhO2026.T3A3.AmpereLawTorus}
    84	\uses{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTTorus, def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTWinding}
    85	Ampère's law $\oint \vec{H}\cdot d\vec{\ell} = I_C$ specialized to the
    86	densely wound thin torus: $H = N\,I\,A / V$, with the enclosed free current
    87	$I_C = N I$ through the mean circle. Assumed governing-law input.
    88	\end{definition}
    89	\begin{proof}
    90	Packaging/definition; nothing derived.
    91	\end{proof}
    92	
    93	\begin{lemma}[Mean circumference in $V/A$ form]
    94	\label{lem:IPhO2026Problems_problem_IPhO_2026_3_A_3:meanCircumference_eq}
    95	\lean{IPhO2026.T3A3.meanCircumference_eq}
    96	\uses{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTTorus}
    97	The mean circumference of the thin torus is $2\pi R = V/A$ — the geometric
    98	bridge from the loop form of Ampère's law to the $V/A$ form.
    99	\end{lemma}
   100	\begin{proof}
   101	Divide the thin-torus identity $V = 2\pi R\,A$ by $A > 0$ and rearrange.
   102	\end{proof}
   103	
   104	\begin{definition}[Uniform core field state]
   105	\label{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTFieldState}
   106	\lean{IPhO2026.T3A3.PmTFieldState}
   107	The instantaneous, approximately uniform electromagnetic state of the core:
   108	field intensity $H$ (A/m), flux density $B$ (T), magnetization $M$ (A/m).
   109	\end{definition}
   110	\begin{proof}
   111	Packaging/definition; nothing derived.
   112	\end{proof}
   113	
   114	\begin{definition}[Constitutive law $B = \mu_0(H+M)$]
   115	\label{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:ConstitutiveBH}
   116	\lean{IPhO2026.T3A3.ConstitutiveBH}
   117	\uses{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTFieldState}
   118	The material's constitutive relation $B = \mu_0 H + \mu_0 M$, an assumed
   119	governing-law input, with $\mu_0$ the free-space permeability supplied by
   120	the PhysLean \texttt{FreeSpace} record $\mathcal{F}$.
   121	\end{definition}
   122	\begin{proof}
   123	Packaging/definition; nothing derived.
   124	\end{proof}
   125	
   126	\begin{definition}[Admissible infinitesimal process]
   127	\label{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTVariation}
   128	\lean{IPhO2026.T3A3.PmTVariation}
   129	\uses{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTTorus, def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTWinding, def:IPhO2026Problems_problem_IPhO_2026_3_A_3:AmpereLawTorus, def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTFieldState, def:IPhO2026Problems_problem_IPhO_2026_3_A_3:ConstitutiveBH}
   130	A current core state together with increments $dB$, $dH$, $dM$ (T, A/m,
   131	A/m) produced by a slight change of the source current. Hypothesis fields
   132	(all assumed governing-law inputs, not conclusions): Ampère's law holds for
   133	the state $H$, the constitutive law holds for the state, and the linearized
   134	constitutive law $dB = \mu_0\,dH + \mu_0\,dM$ holds for the increments.
   135	The increments are formal differentials packaged as reals — a named scalar
   136	projection of the one-form language; this is the documented modeling choice
   137	of this file.
   138	\end{definition}
   139	\begin{proof}
   140	Packaging/definition; nothing derived.
   141	\end{proof}
   142	
   143	\begin{lemma}[Vacuum-core $B$-increment]
   144	\label{lem:IPhO2026Problems_problem_IPhO_2026_3_A_3:dB_of_vacuum_core}
   145	\lean{IPhO2026.T3A3.dB_of_vacuum_core}
   146	For a vacuum core ($M = 0$, hence $dM = 0$) the linearized constitutive law
   147	reduces to $dB = \mu_0\,dH$: from $dB = \mu_0\,dH + \mu_0\cdot 0$ conclude
   148	$dB = \mu_0\,dH$. This justifies the vacuum-core contribution in the work
   149	budget below.
   150	\end{lemma}
   151	\begin{proof}
   152	Simplify the additive term $\mu_0\cdot 0$ to zero and cancel.
   153	\end{proof}
   154	
   155	\begin{definition}[Infinitesimal work budget of the Pm-T]
   156	\label{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTWorkBudget}
   157	\lean{IPhO2026.T3A3.PmTWorkBudget}
   158	\uses{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTVariation}
   159	The three licensed inputs of subquestion A.3 (all work entries in joules,
   160	with the sign convention that work entering the paramagnetic torus is
   161	positive): the part-A.2 source-work law $dW_{\mathrm{emf}} = V\,H\,dB$;
   162	the problem statement's split
   163	$dW_{\mathrm{emf}} = dW_{\mathrm{vac}} + dW$ into a vacuum-core part and
   164	the work done on the material itself; and the vacuum-core contribution
   165	$dW_{\mathrm{vac}} = \mu_0\,V\,H\,dH$ (the A.2 law applied to a core with
   166	$M = 0$, with $H$ unchanged because Ampère's law sees only the free
   167	current). The A.3 answer $dW = \mu_0 V H dM$ is \emph{not} among these
   168	fields.
   169	\end{definition}
   170	\begin{proof}
   171	Packaging/definition; nothing derived.
   172	\end{proof}
   173	
   174	\begin{lemma}[Material work as the source-minus-vacuum difference]
   175	\label{lem:IPhO2026Problems_problem_IPhO_2026_3_A_3:dW_eq_sub_vac}
   176	\lean{IPhO2026.T3A3.dW_eq_sub_vac}
   177	\uses{def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTWorkBudget}
   178	Subtracting the vacuum-core contribution isolates the work done on the
   179	material: $dW = dW_{\mathrm{emf}} - dW_{\mathrm{vac}}$.
   180	\end{lemma}
   181	\begin{proof}
   182	Rearrange the split identity
   183	$dW_{\mathrm{emf}} = dW_{\mathrm{vac}} + dW$ by subtracting
   184	$dW_{\mathrm{vac}}$ from both sides.
   185	\end{proof}
   186	
   187	\begin{lemma}[Material work through the increments of $H$ and $B$]
   188	\label{lem:IPhO2026Problems_problem_IPhO_2026_3_A_3:dW_eq_VH_dB_sub_mu0_dH}
   189	\lean{IPhO2026.T3A3.dW_eq_VH_dB_sub_mu0_dH}
   190	\uses{lem:IPhO2026Problems_problem_IPhO_2026_3_A_3:dW_eq_sub_vac}
   191	Substituting the licensed inputs expresses the material work as
   192	$dW = V\,H\,(dB - \mu_0\,dH)$.
   193	\end{lemma}
   194	\begin{proof}
   195	Replace $dW_{\mathrm{emf}}$ by $V\,H\,dB$ (part A.2) and
   196	$dW_{\mathrm{vac}}$ by $\mu_0\,V\,H\,dH$ in the difference
   197	$dW = dW_{\mathrm{emf}} - dW_{\mathrm{vac}}$, then factor out $V\,H$.
   198	\end{proof}
   199	
   200	\begin{theorem}[A.3 target: work done on the paramagnetic material]
   201	\label{thm:IPhO2026Problems_problem_IPhO_2026_3_A_3:dW_eq_mu0_V_H_dM}
   202	\lean{IPhO2026.T3A3.dW_eq_mu0_V_H_dM}
   203	\uses{lem:IPhO2026Problems_problem_IPhO_2026_3_A_3:dW_eq_VH_dB_sub_mu0_dH, def:IPhO2026Problems_problem_IPhO_2026_3_A_3:ConstitutiveBH, def:IPhO2026Problems_problem_IPhO_2026_3_A_3:PmTVariation}
   204	The work done on the paramagnetic material itself when the magnetization
   205	changes by $dM$ is
   206	\[ dW = \mu_0\,V\,H\,dM, \]
   207	the recorded official answer $dW = \alpha\,V\,\mu_0\,H\,dM$ at $\alpha = 1$.
   208	This is the conclusion of the derivation; it never appears as a hypothesis.
   209	\end{theorem}
   210	\begin{proof}
   211	Start from $dW = V\,H\,(dB - \mu_0\,dH)$ and substitute the linearized
   212	constitutive law $dB = \mu_0\,dH + \mu_0\,dM$ of the admissible process;
   213	the terms $V\,H\,\mu_0\,dH$ cancel, leaving $dW = \mu_0\,V\,H\,dM$.
   214	\end{proof}
   215	% --- Archon physics formalization source end ---

[exit 0]

